import { createHash } from "crypto";

export interface RefreshTokenRecord {
    userId: string;
    expiresAt: number;
}

// Store hashed refresh tokens, not raw tokens
export const refreshTokens = new Map<string, RefreshTokenRecord>();

// Hash refresh token using SHA-256
// If someone obtains access to our in-memory token storage, they won't immediately 
// obtain usable refresh tokens.
//
// We use SHA-256 because refresh tokens are cryptographically random, high-entropy 
// values generated by our JWT signing process. Unlike passwords, they don't need 
// a slow password-hashing algorithm such as bcrypt.
//
export const hashRefreshToken = (token: string): string => {
    return createHash("sha256")
        .update(token)
        .digest("hex");
};

// Save refresh token
export const saveRefreshToken = (
  token: string,
  userId: string,
  expiresAt: number
): void => {
  refreshTokens.set(hashRefreshToken(token), {
    userId,
    expiresAt
  });
};

export const findRefreshToken = (token: string): RefreshTokenRecord | undefined => {
  return refreshTokens.get(hashRefreshToken(token));
};

export const deleteRefreshToken = (token: string): void => {
  refreshTokens.delete(hashRefreshToken(token));
};